-- =========================================================================
-- SALICORNIA DIGITAL — Base de datos MariaDB / MySQL
-- =========================================================================
-- Versión  : 1.0
-- Fecha    : Mayo 2026
-- Autores  : Marismas Biomed
-- Script   : Datos reales de las instalaciones Marambay y Cupimar
--
-- ESTRUCTURA FÍSICA:
--   MARAMBAY : 2 instalaciones × 100 secciones × 5 planchas × 32 macetas
--              = 500 planchas · 16 000 macetas
--   CUPIMAR  : 1 instalación  × 28 secciones  × 40 planchas × 32 macetas
--              = 1 120 planchas · 35 840 macetas
--   TOTAL    : 128 secciones · 1 620 planchas · 51 840 macetas
-- =========================================================================

SET NAMES utf8mb4;
SET time_zone = '+00:00';
SET foreign_key_checks = 0;
SET sql_mode = 'NO_AUTO_VALUE_ON_ZERO';

-- ─────────────────────────────────────────────────────────────────────────────
-- BASE DE DATOS
-- ─────────────────────────────────────────────────────────────────────────────
CREATE DATABASE IF NOT EXISTS salicornia_db
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE salicornia_db;

-- =========================================================================
-- TABLA 0: INSTALACIONES
-- =========================================================================
CREATE TABLE IF NOT EXISTS instalaciones (
  id            INT UNSIGNED     NOT NULL AUTO_INCREMENT,
  nombre        VARCHAR(100)     NOT NULL,
  descripcion   TEXT,
  ubicacion_lat DECIMAL(10,8),
  ubicacion_lon DECIMAL(11,8),
  municipio     VARCHAR(100)     DEFAULT 'San Fernando',
  provincia     VARCHAR(100)     DEFAULT 'Cádiz',
  creado_en     DATETIME         DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_instalacion_nombre (nombre)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- =========================================================================
-- TABLA 1: SECCIONES
-- =========================================================================
CREATE TABLE IF NOT EXISTS secciones (
  id                  INT UNSIGNED NOT NULL AUTO_INCREMENT,
  instalacion_id      INT UNSIGNED NOT NULL,
  codigo              VARCHAR(20)  NOT NULL,           -- S-001 … S-100
  descripcion         TEXT,
  ubicacion_lat       DECIMAL(10,8),
  ubicacion_lon       DECIMAL(11,8),
  superficie_total_m2 DECIMAL(10,2),
  tipo_cultivo        VARCHAR(50)  DEFAULT 'Marisma',  -- Marisma | Hidroponia
  estado              VARCHAR(50)  DEFAULT 'Activa',   -- Activa | Parada | Mantenimiento
  creado_en           DATETIME     DEFAULT CURRENT_TIMESTAMP,
  actualizado_en      DATETIME     DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_seccion_inst_codigo (instalacion_id, codigo),
  CONSTRAINT fk_seccion_instalacion FOREIGN KEY (instalacion_id) REFERENCES instalaciones(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX idx_secciones_estado       ON secciones(estado);
CREATE INDEX idx_secciones_instalacion  ON secciones(instalacion_id);

-- Secciones MARAMBAY (S-001 .. S-100)

-- Secciones CUPIMAR (S-001 .. S-028)


-- =========================================================================
-- TABLA 2: PLANCHAS
-- =========================================================================
CREATE TABLE IF NOT EXISTS planchas (
  id             INT UNSIGNED NOT NULL AUTO_INCREMENT,
  seccion_id     INT UNSIGNED NOT NULL,
  codigo         VARCHAR(20)  NOT NULL,           -- PL-001 … PL-040
  nombre         VARCHAR(120),
  identificador  VARCHAR(50)  NOT NULL,           -- S-001_PL-001 (identificador global único)
  superficie_m2  DECIMAL(10,2) NOT NULL DEFAULT 30.00,
  n_macetas      SMALLINT UNSIGNED NOT NULL DEFAULT 32,
  variedad       VARCHAR(100),
  fecha_siembra  DATE,
  estado         VARCHAR(50)  DEFAULT 'Activa',
  -- Activa | Preparacion | Semillero | Crecimiento | Maduracion | Cosechada | Mantenimiento
  qr_code        VARCHAR(255),
  creado_en      DATETIME     DEFAULT CURRENT_TIMESTAMP,
  actualizado_en DATETIME     DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_plancha_identificador (identificador),
  CONSTRAINT fk_plancha_seccion FOREIGN KEY (seccion_id) REFERENCES secciones(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX idx_planchas_seccion  ON planchas(seccion_id);
CREATE INDEX idx_planchas_estado   ON planchas(estado);
CREATE INDEX idx_planchas_codigo   ON planchas(codigo);

-- Planchas MARAMBAY: 100 secciones × 5 planchas = 500 planchas

-- Planchas CUPIMAR: 28 secciones × 40 planchas = 1 120 planchas


-- =========================================================================
-- TABLA 3: MACETAS
-- =========================================================================
CREATE TABLE IF NOT EXISTS macetas (
  id              INT UNSIGNED NOT NULL AUTO_INCREMENT,
  plancha_id      INT UNSIGNED NOT NULL,
  numero_posicion VARCHAR(10)  NOT NULL,   -- M-001 … M-032
  identificador   VARCHAR(80)  NOT NULL,   -- S-001_PL-001_M-001
  estado          VARCHAR(50)  DEFAULT 'Activa',
  -- Activa | Enferma | Descartada | Cosechada
  creado_en       DATETIME     DEFAULT CURRENT_TIMESTAMP,
  actualizado_en  DATETIME     DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_maceta_plancha_pos (plancha_id, numero_posicion),
  UNIQUE KEY uq_maceta_identificador (identificador),
  CONSTRAINT fk_maceta_plancha FOREIGN KEY (plancha_id) REFERENCES planchas(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX idx_macetas_plancha ON macetas(plancha_id);
CREATE INDEX idx_macetas_estado  ON macetas(estado);

-- =========================================================================
-- GENERACIÓN AUTOMÁTICA DE MACETAS
-- =========================================================================
-- Procedimiento almacenado para generar las 51 840 macetas automáticamente
-- a partir de las planchas existentes.
-- =========================================================================

DROP PROCEDURE IF EXISTS generar_macetas;

DELIMITER $$
CREATE PROCEDURE generar_macetas()
BEGIN
  DECLARE done        INT DEFAULT 0;
  DECLARE pid         INT UNSIGNED;
  DECLARE p_ident     VARCHAR(50);
  DECLARE m_num       SMALLINT;
  DECLARE mcode       VARCHAR(10);
  DECLARE m_ident     VARCHAR(80);

  DECLARE cur CURSOR FOR
    SELECT id, identificador FROM planchas;

  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

  OPEN cur;

  read_loop: LOOP
    FETCH cur INTO pid, p_ident;
    IF done THEN LEAVE read_loop; END IF;

    SET m_num = 1;
    WHILE m_num <= 32 DO
      SET mcode   = CONCAT('M-', LPAD(m_num, 3, '0'));
      SET m_ident = CONCAT(p_ident, '_', mcode);

      VALUES (pid, mcode, m_ident, 'Activa');

      SET m_num = m_num + 1;
    END WHILE;
  END LOOP;

  CLOSE cur;
END$$
DELIMITER ;

-- Ejecutar el procedimiento para generar todas las macetas
CALL generar_macetas();

-- Una vez ejecutado puedes eliminar el procedimiento si quieres:
-- DROP PROCEDURE IF EXISTS generar_macetas;


-- =========================================================================
-- TABLA 4: REGISTROS DE CAMPO (Cuaderno)
-- =========================================================================
CREATE TABLE IF NOT EXISTS registros_campo (
  id                          INT UNSIGNED  NOT NULL AUTO_INCREMENT,
  plancha_id                  INT UNSIGNED  NOT NULL,
  maceta_id                   INT UNSIGNED,
  fecha                       DATE          NOT NULL,
  hora                        TIME,
  altura_cm                   DECIMAL(5,1)  CHECK (altura_cm > 0),
  n_ramificaciones            TINYINT UNSIGNED,
  biomasa_g                   DECIMAL(8,2)  CHECK (biomasa_g >= 0),
  observaciones               TEXT,
  foto_url                    VARCHAR(255),
  candidata_seleccion_genetica TINYINT(1)   DEFAULT 0,
  registrado_por              VARCHAR(100),
  creado_en                   DATETIME      DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT fk_rc_plancha FOREIGN KEY (plancha_id) REFERENCES planchas(id) ON DELETE CASCADE,
  CONSTRAINT fk_rc_maceta  FOREIGN KEY (maceta_id)  REFERENCES macetas(id)  ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX idx_rc_plancha   ON registros_campo(plancha_id);
CREATE INDEX idx_rc_maceta    ON registros_campo(maceta_id);
CREATE INDEX idx_rc_fecha     ON registros_campo(fecha);
CREATE INDEX idx_rc_candidata ON registros_campo(candidata_seleccion_genetica);

-- =========================================================================
-- TABLA 5: FOTOS E INCIDENCIAS
-- =========================================================================
CREATE TABLE IF NOT EXISTS fotos (
  id                INT UNSIGNED NOT NULL AUTO_INCREMENT,
  plancha_id        INT UNSIGNED NOT NULL,
  maceta_id         INT UNSIGNED,
  fecha             DATE         NOT NULL,
  hora              TIME,
  url_imagen        VARCHAR(255) NOT NULL,
  comentario        TEXT,
  es_incidencia     TINYINT(1)   DEFAULT 0,
  tipo_incidencia   VARCHAR(100),
  severidad         VARCHAR(20)  DEFAULT 'Media',
  -- Baja | Media | Alta | Critica
  estado_incidencia VARCHAR(50)  DEFAULT 'Abierta',
  -- Abierta | Seguimiento | Resuelta | Descartada
  resolucion_notas  TEXT,
  registrado_por    VARCHAR(100),
  resuelto_por      VARCHAR(100),
  fecha_resolucion  DATE,
  creado_en         DATETIME     DEFAULT CURRENT_TIMESTAMP,
  actualizado_en    DATETIME     DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT fk_foto_plancha FOREIGN KEY (plancha_id) REFERENCES planchas(id) ON DELETE CASCADE,
  CONSTRAINT fk_foto_maceta  FOREIGN KEY (maceta_id)  REFERENCES macetas(id)  ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX idx_fotos_plancha    ON fotos(plancha_id);
CREATE INDEX idx_fotos_incidencia ON fotos(es_incidencia);
CREATE INDEX idx_fotos_severidad  ON fotos(severidad);
CREATE INDEX idx_fotos_estado     ON fotos(estado_incidencia);
CREATE INDEX idx_fotos_fecha      ON fotos(fecha);

-- =========================================================================
-- TABLA 6: SENSORES — LECTURAS IOT
-- =========================================================================
CREATE TABLE IF NOT EXISTS sensores_lecturas (
  id                 INT UNSIGNED   NOT NULL AUTO_INCREMENT,
  plancha_id         INT UNSIGNED   NOT NULL,
  nombre_sensor      VARCHAR(100),
  oxigeno_disuelto   DECIMAL(4,1),    -- mg/L  (ideal 5-8)
  salinidad          DECIMAL(5,1),    -- PSU   (ideal 28-35)
  nitratos           DECIMAL(5,2),    -- mg/L  (ideal 10-20)
  temperatura_agua   DECIMAL(4,1),    -- °C    (ideal 18-25)
  ph                 DECIMAL(4,2),    -- pH    (ideal 7.0-8.5)
  nivel_agua         DECIMAL(5,2),    -- m
  potasio            DECIMAL(6,2),    -- mg/L
  fosforo            DECIMAL(6,2),    -- mg/L
  intensidad_luz     DECIMAL(7,0),    -- lux
  horas_luz          DECIMAL(4,1),    -- h/día
  fecha_lectura      DATETIME         NOT NULL,
  creado_en          DATETIME         DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  CONSTRAINT fk_sensor_plancha FOREIGN KEY (plancha_id) REFERENCES planchas(id) ON DELETE CASCADE,
  CONSTRAINT ck_ph CHECK (ph > 0 AND ph <= 14),
  CONSTRAINT ck_salinidad CHECK (salinidad >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX idx_sensor_plancha ON sensores_lecturas(plancha_id);
CREATE INDEX idx_sensor_fecha   ON sensores_lecturas(fecha_lectura);
CREATE INDEX idx_sensor_reciente ON sensores_lecturas(plancha_id, fecha_lectura);

-- =========================================================================
-- TABLA 7: DATOS AMBIENTALES (mareas + meteorología)
