  temperatura_maxima   DECIMAL(4,1),
  temperatura_minima   DECIMAL(4,1),
  humedad              DECIMAL(5,1),
  viento_velocidad     DECIMAL(5,1),
  viento_velocidad_max DECIMAL(5,1),
  viento_direccion     VARCHAR(20),
  lluvia_mm            DECIMAL(5,1),
