-- =========================================================================
-- TABLA 8: COSECHAS
-- =========================================================================
CREATE TABLE IF NOT EXISTS cosechas (
  id                       INT UNSIGNED NOT NULL AUTO_INCREMENT,
  lote_id                  VARCHAR(50)  NOT NULL,
  plancha_id               INT UNSIGNED NOT NULL,
  fecha_cosecha            DATE         NOT NULL,
  canal_cosecha            VARCHAR(50),
  altura_marea             DECIMAL(4,2),
  temperatura_agua_cosecha DECIMAL(4,1),
  peso_kg                  DECIMAL(8,2) NOT NULL,
  n_plantas                SMALLINT UNSIGNED,
  observaciones            TEXT,
  foto_cosecha             VARCHAR(255),
  cosechado_por            VARCHAR(100),
  registrado_por           VARCHAR(100),
  creado_en                DATETIME     DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_cosecha_lote (lote_id),
  CONSTRAINT fk_cosecha_plancha FOREIGN KEY (plancha_id) REFERENCES planchas(id) ON DELETE RESTRICT,
  CONSTRAINT ck_peso_kg CHECK (peso_kg > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX idx_cosecha_lote   ON cosechas(lote_id);
CREATE INDEX idx_cosecha_plancha ON cosechas(plancha_id);
CREATE INDEX idx_cosecha_fecha  ON cosechas(fecha_cosecha);

-- =========================================================================
-- TABLA 9: LOTES TRAZABILIDAD
-- =========================================================================
CREATE TABLE IF NOT EXISTS lotes_trazabilidad (
  id                   INT UNSIGNED  NOT NULL AUTO_INCREMENT,
  lote_id              VARCHAR(50)   NOT NULL,
  plancha_id           INT UNSIGNED  NOT NULL,
  cosecha_id           INT UNSIGNED  NOT NULL,
  fecha_cosecha        DATE          NOT NULL,
  fecha_lavado         DATE,
  fecha_secado         DATE,
  fecha_envasado       DATE,
  estado               VARCHAR(50)   DEFAULT 'Pendiente',
  -- Pendiente | Lavando | Secando | Envasando | Completado | Distribuido
  peso_inicial_kg      DECIMAL(8,2),
  peso_tras_lavado_kg  DECIMAL(8,2),
  peso_tras_secado_kg  DECIMAL(8,2),
  peso_final_kg        DECIMAL(8,2),
  humedad_inicial      DECIMAL(5,1),
  humedad_final        DECIMAL(5,1),
  analisis_salinidad   DECIMAL(5,2),
  analisis_humedad     DECIMAL(5,1),
  qr_distribucion      VARCHAR(255),
  notas_lavado         TEXT,
  notas_secado         TEXT,
  notas_envasado       TEXT,
  lavado_por           VARCHAR(100),
  secado_por           VARCHAR(100),
  envasado_por         VARCHAR(100),
  creado_en            DATETIME      DEFAULT CURRENT_TIMESTAMP,
  actualizado_en       DATETIME      DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uq_traza_lote (lote_id),
  CONSTRAINT fk_traza_lote    FOREIGN KEY (lote_id)    REFERENCES cosechas(lote_id) ON DELETE CASCADE,
  CONSTRAINT fk_traza_plancha FOREIGN KEY (plancha_id) REFERENCES planchas(id)     ON DELETE RESTRICT,
  CONSTRAINT fk_traza_cosecha FOREIGN KEY (cosecha_id) REFERENCES cosechas(id)     ON DELETE CASCADE,
  CONSTRAINT ck_humedad CHECK (humedad_final IS NULL OR (humedad_final >= 0 AND humedad_final <= 100))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX idx_traza_lote   ON lotes_trazabilidad(lote_id);
CREATE INDEX idx_traza_estado ON lotes_trazabilidad(estado);
CREATE INDEX idx_traza_fecha  ON lotes_trazabilidad(fecha_cosecha);

