-- =========================================================================
-- VISTAS ÚTILES
-- =========================================================================

-- Vista: estado completo de cada plancha con su sección e instalación
CREATE OR REPLACE VIEW v_planchas_estado AS
SELECT
  p.id,
  p.identificador,
  p.codigo         AS plancha_codigo,
  p.nombre         AS plancha_nombre,
  s.codigo         AS seccion_codigo,
  i.nombre         AS instalacion,
  p.variedad,
  p.fecha_siembra,
  DATEDIFF(CURDATE(), p.fecha_siembra) AS edad_dias,
  p.estado,
  p.superficie_m2,
  p.n_macetas,
  COUNT(DISTINCT m.id)                                      AS macetas_totales,
  COUNT(DISTINCT CASE WHEN m.estado = 'Activa' THEN m.id END) AS macetas_activas,
  COUNT(DISTINCT rc.id)                                     AS registros_campo,
  MAX(rc.fecha)                                             AS ultimo_registro
FROM planchas p
JOIN secciones   s ON p.seccion_id     = s.id
JOIN instalaciones i ON s.instalacion_id = i.id
LEFT JOIN macetas m ON m.plancha_id    = p.id
LEFT JOIN registros_campo rc ON rc.plancha_id = p.id
GROUP BY p.id, s.id, i.id;

-- Vista: última lectura de sensor por plancha
CREATE OR REPLACE VIEW v_sensores_ultimas AS
SELECT sl.*
FROM sensores_lecturas sl
INNER JOIN (
  SELECT plancha_id, MAX(fecha_lectura) AS max_fecha
  FROM sensores_lecturas
  GROUP BY plancha_id
) latest ON sl.plancha_id = latest.plancha_id AND sl.fecha_lectura = latest.max_fecha;

-- Vista: incidencias activas con datos de plancha
CREATE OR REPLACE VIEW v_incidencias_activas AS
SELECT
  f.id,
  f.plancha_id,
  p.identificador  AS plancha_ident,
  p.codigo         AS plancha_codigo,
  s.codigo         AS seccion_codigo,
  i.nombre         AS instalacion,
  f.maceta_id,
  f.tipo_incidencia,
  f.severidad,
  f.estado_incidencia,
  f.fecha,
  f.url_imagen,
  f.comentario,
  f.registrado_por,
  DATEDIFF(CURDATE(), f.fecha) AS dias_abierta
FROM fotos f
JOIN planchas    p ON f.plancha_id    = p.id
JOIN secciones   s ON p.seccion_id    = s.id
JOIN instalaciones i ON s.instalacion_id = i.id
WHERE f.es_incidencia = 1
  AND f.estado_incidencia IN ('Abierta', 'Seguimiento')
ORDER BY
  FIELD(f.severidad, 'Critica', 'Alta', 'Media', 'Baja'),
  dias_abierta DESC;

-- Vista: KPIs globales
CREATE OR REPLACE VIEW v_kpi_globales AS
SELECT
  (SELECT COUNT(*) FROM instalaciones)                                    AS instalaciones_total,
  (SELECT COUNT(*) FROM secciones  WHERE estado = 'Activa')               AS secciones_activas,
  (SELECT COUNT(*) FROM planchas   WHERE estado IN ('Crecimiento','Activa','Maduracion')) AS planchas_en_cultivo,
  (SELECT COUNT(*) FROM macetas    WHERE estado = 'Activa')               AS macetas_activas,
  (SELECT COALESCE(SUM(peso_kg),0) FROM cosechas
    WHERE fecha_cosecha >= DATE_SUB(CURDATE(), INTERVAL 30 DAY))          AS kg_cosechado_mes,
  (SELECT COUNT(*) FROM fotos
    WHERE es_incidencia = 1 AND estado_incidencia IN ('Abierta','Seguimiento')) AS incidencias_abiertas,
  (SELECT ROUND(AVG(DATEDIFF(CURDATE(), fecha_siembra)),0) FROM planchas
    WHERE fecha_siembra IS NOT NULL
      AND estado IN ('Crecimiento','Maduracion','Activa'))                 AS edad_promedio_dias;

-- Vista: resumen por instalación
CREATE OR REPLACE VIEW v_resumen_instalaciones AS
SELECT
  i.id,
  i.nombre,
  COUNT(DISTINCT s.id)   AS total_secciones,
  COUNT(DISTINCT p.id)   AS total_planchas,
  COUNT(DISTINCT m.id)   AS total_macetas,
  SUM(p.superficie_m2)   AS superficie_total_m2
FROM instalaciones i
LEFT JOIN secciones  s ON s.instalacion_id = i.id
LEFT JOIN planchas   p ON p.seccion_id = s.id
LEFT JOIN macetas    m ON m.plancha_id = p.id
GROUP BY i.id;



-- =========================================================================
-- TRIGGERS
-- =========================================================================

-- Trigger: generar qr_code automáticamente al insertar plancha
DROP TRIGGER IF EXISTS trg_qr_plancha;
DELIMITER $$
CREATE TRIGGER trg_qr_plancha
BEFORE INSERT ON planchas
FOR EACH ROW
BEGIN
  IF NEW.qr_code IS NULL OR NEW.qr_code = '' THEN
    SET NEW.qr_code = CONCAT('QR-', NEW.identificador);
  END IF;
END$$
DELIMITER ;

-- Trigger: actualizar actualizado_en en secciones
DROP TRIGGER IF EXISTS trg_seccion_update;
DELIMITER $$
CREATE TRIGGER trg_seccion_update
BEFORE UPDATE ON secciones
FOR EACH ROW
BEGIN
  SET NEW.actualizado_en = CURRENT_TIMESTAMP;
END$$
DELIMITER ;

